document.querySelectorAll('[data-lab="PM03-I1"]').forEach(root=>{const g=k=>root.querySelector('[data-field="'+k+'"]'),zh=root.dataset.lang==='zh';const update=()=>{const f=+g('fraction').value/100,mn=(1-f)*20000+f*200000,mw=((1-f)*20000**2+f*200000**2)/mn,w=f*200000/mn;g('value').textContent=(f*100).toFixed(0)+'%';g('number').setAttribute('width',f*550);g('mass').setAttribute('width',w*550);g('result').textContent=(zh?'长链质量占比 ':'Long-chain mass fraction ')+(w*100).toFixed(2)+'%; Mₙ = '+mn.toFixed(0)+' g/mol; M_w = '+mw.toFixed(0)+' g/mol; Đ = '+(mw/mn).toFixed(3)+(zh?'。两组摩尔质量为20 000与200 000 g/mol。长链每条质量为短链的10倍，因此数量比例与质量比例不同。':' . The two molar masses are 20,000 and 200,000 g/mol. Each long chain has ten times the mass of a short chain, so count and mass fractions differ.');};g('fraction').addEventListener('input',update);update();});